WITH lines AS (SELECT id, service, log_ts, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, value) SELECT level, CASE WHEN status_code >= 420 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, COUNT(*) AS row_count, MAX(log_ts) AS last_seen, COUNT(*) FILTER (WHERE level = 'DEBUG') AS debug_rows, GROUPING_ID() AS grouping_id FROM lines GROUP BY ROLLUP (level, CASE WHEN status_code >= 420 THEN 'PREMIUM' ELSE 'STANDARD' END);
